function write(next){return new Promise((resolve,reject)=>{let tx=db.transaction('planner','readwrite');tx.objectStore('planner').put(next,'data');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}async function commit(next){document.querySelector('.local').textContent='◌ Saving…';try{await write(next);state=next;render();document.querySelector('.local').textContent='● Saved on this device';return true}catch(e){document.querySelector('.local').textContent='⚠ Changes not saved';alert('Could not save. Your previous data is unchanged. Storage may be full or unavailable. Export a backup before clearing anything.');return false}}async function mutate(fn){let next=structuredClone(state);fn(next);return commit(next)}
function go(p,f=''){window.scrollTo({top:0,behavior:'instant'});page=p;filter=f;query='';statusFilter='';render()}function heading(title,sub,action=''){return `<div class="heading"><div><div class="eyebrow">BHARADWAJ FAMILIES HOUSE CEREMONY</div><h1>${title}</h1><p class="subtitle">${sub}</p></div>${action}</div>`}function btn(text,act,primary=false){return `<button class="btn ${primary?'primary':''}" onclick="${act}">${text}</button>`}function taskRow(t){return `<div class="task-row"><input type="checkbox" aria-label="Complete ${esc(t.title)}" ${t.status==='Completed'?'checked':''} onchange="completeTask('${t.id}',this.checked)"><div class="task-name ${t.status==='Completed'?'done':''}" onclick="editTask('${t.id}')">${esc(t.title)}<small>${esc(t.event)} · ${esc(t.owner||'Unassigned')} · <span class="${t.due&&t.due<today()&&t.status!=='Completed'?'overdue':''}">${dateLabel(t.due)}</span></small></div><span class="pill">${esc(t.status)}</span><button class="textbtn" aria-label="Edit ${esc(t.title)}" onclick="editTask('${t.id}')">↗</button></div>`}async function completeTask(id,v){await mutate(s=>s.tasks.find(t=>t.id===id).status=v?'Completed':'Not started')}
function render(){ $('#nav').innerHTML=pages.map(([p,i])=>`<button class="${page===p?'active':''}" onclick="go('${p}')"><span aria-hidden="true">${i}</span>${p}</button>`).join('');let html='',completed=state.tasks.filter(t=>t.status==='Completed').length,total=state.tasks.length,cost=state.tasks.reduce((s,t)=>s+Number(t.cost||0),0),paid=state.tasks.reduce((s,t)=>s+Number(t.paid||0),0);if(page==='Overview'){let days=Math.max(0,Math.ceil((new Date('2026-11-15T00:00:00+05:30')-new Date())/86400000));html=heading('A beautiful beginning, Hrishitha.','A little planning today. A celebration to remember.',btn('+ Add task',"editTask()",true))+`<section class="hero"><div><div class="eyebrow">OUR HOME · OUR PEOPLE · OUR CELEBRATION</div><h2>Making room for<br>a lifetime of memories.</h2><p>Sunday, 15 November 2026 &nbsp; · &nbsp; Bharadwaj family</p></div><div class="countdown"><strong>${days}</strong><small>DAYS TO GO</small></div></section><section class="stats"><div class="stat"><label>PLANNING PROGRESS</label><strong>${Math.round(completed/total*100)||0}%</strong><small>${completed} of ${total} tasks complete</small></div><div class="stat"><label>GUESTS EXPECTED</label><strong>100 <span style="font-size:16px;color:#aaa">/</span> 450</strong><small>Morning pooja / Evening party</small></div><div class="stat"><label>CONFIRMED COSTS</label><strong>${money(cost)}</strong><small>${money(paid)} paid so far</small></div><div class="stat"><label>NEEDS ATTENTION</label><strong>${state.tasks.filter(t=>['Blocked','Exploring','Shortlisted'].includes(t.status)).length}</strong><small>Open decisions & blocked tasks</small></div></section><div class="section-top"><h2>Three moments. One celebration.</h2><span class="eyebrow" style="margin:0">THE CELEBRATION PLAN</span></div><section class="events">${events.map((e,i)=>{let ts=state.tasks.filter(t=>t.event===e),done=ts.filter(t=>t.status==='Completed').length;return `<article class="event" tabindex="0" role="button" onclick="go('Tasks','${e}')" onkeydown="if(event.key==='Enter')go('Tasks','${e}')"><div class="event-art"><span>${['❋\uFE0E','☼\uFE0E','✧\uFE0E'][i]}</span><small>${i===0?'14 NOV · 6:30 PM':'15 NOV · '+(i===1?'MORNING':'EVENING')}</small></div><h3>${e}</h3><p style="font-size:12px">${['An evening of colour & togetherness','Blessings for a beautiful new chapter','Good food, music & familiar faces'][i]}</p><span class="chip">${['Hrishitha & the ladies','100 guests','450 guests'][i]}</span><div class="progress"><i style="width:${done/ts.length*100}%"></i></div><div class="meta"><span>${done}/${ts.length} tasks complete</span><span>View plan ↗</span></div></article>`}).join('')}</section><section class="two-col"><div class="panel"><div class="section-top" style="margin-top:0"><h2>Next on your list</h2><button class="textbtn" onclick="go('Tasks')">All tasks →</button></div>${state.tasks.filter(t=>t.status!=='Completed').sort((a,b)=>(a.due||'9999').localeCompare(b.due||'9999')).slice(0,4).map(taskRow).join('')||'<p>Everything is complete. Enjoy the celebration!</p>'}</div><div class="panel"><div class="eyebrow">A LITTLE PEACE OF MIND</div><h2>Your plans, safely with you.</h2><p style="font-size:13px">Everything you add stays in this browser, on this device. Keep a backup of your plans and precious references.</p><div class="notice"><strong>${state.lastBackup?'Last backup: '+new Date(state.lastBackup).toLocaleString('en-IN'):'Your first backup is waiting'}</strong><br>Export after making important updates.</div><button class="textbtn" style="margin-top:15px" onclick="exportBackup()">Download a backup ↗</button></div></section>`}
if(page==='Tasks'){let ts=state.tasks.filter(t=>(!filter||t.event===filter)&&(!statusFilter||t.status===statusFilter)&&(!query||(t.title+' '+t.owner+' '+t.notes).toLowerCase().includes(query.toLowerCase())));html=heading('Every detail, taken care of.','Plan, shortlist, confirm — and tick it off.',btn('+ Add task',"editTask()",true))+`<div class="toolbar"><input type="search" aria-label="Search tasks" placeholder="Search tasks, notes or owners…" value="${esc(query)}" oninput="searchTasks(this)"><select aria-label="Filter event" onchange="filter=this.value;render()"><option value="">All celebrations</option>${options(events,filter)}</select><select aria-label="Filter status" onchange="statusFilter=this.value;render()"><option value="">All statuses</option>${options(statuses,statusFilter)}</select></div><div class="list">${ts.map(taskRow).join('')||empty('No matching tasks','Try another filter or add a new task.')}</div>`}
if(page==='Contacts')html=heading('The people behind the day.','Keep every vendor and helpful contact close.',btn('+ Add contact','editContact()',true))+`<div class="grid">${state.contacts.map(c=>`<article class="contact"><span class="chip">${esc(c.role||'Contact')}</span><h3>${esc(c.name)}</h3><p>${esc(c.notes)}</p><p>${esc(c.address)}</p>${c.phone?`<a href="tel:${esc(c.phone.replace(/[^+\d]/g,''))}">Call ${esc(c.phone)}</a><a href="https://wa.me/${esc(c.phone.replace(/\D/g,''))}" target="_blank" rel="noopener">WhatsApp ↗</a>`:'<p>Phone number not added</p>'}${c.email?`<p>${esc(c.email)}</p>`:''}<button class="textbtn" onclick="editContact('${c.id}')">Edit contact →</button></article>`).join('')}</div>`;
if(page==='Moodboard'){let images=[...state.images,...state.tasks.flatMap(t=>t.images.map(i=>({...i,task:t.title,taskId:t.id})))];html=heading('A little inspiration. A clear vision.','Collect the colours, textures and details you love.',btn('+ Add images','addImages()',true))+`<div class="grid">${images.map(i=>`<article class="gallery-item"><a href="${i.data}" download="${esc(i.name)}"><img src="${i.data}" alt="${esc(i.name)}"></a><div><span class="chip">${esc(i.status||'Inspiration')}</span><h3 style="font-size:17px">${esc(i.name)}</h3><p>${esc(i.task||i.category||'General inspiration')}</p><button class="textbtn" onclick="imageStatus('${i.id}')">Change status</button><button class="textbtn" onclick="removeImage('${i.id}')">Remove</button></div></article>`).join('')}</div>${!images.length?empty('Your vision starts here','Upload outfit ideas, flower references, backdrop designs or receipt photos.'):''}`}
if(page==='Guests')html=heading('Make everyone feel at home.','Household RSVPs, dietary needs and table assignments.',btn('+ Add household','editGuest()',true))+`<div class="notice">${state.guests.reduce((a,g)=>a+(g.morning?Number(g.count):0),0)} morning invitees · ${state.guests.reduce((a,g)=>a+(g.evening?Number(g.count):0),0)} evening invitees · ${state.guests.filter(g=>g.rsvp==='Confirmed').reduce((a,g)=>a+Number(g.count),0)} people in confirmed households</div><div class="grid" style="margin-top:20px">${state.guests.map(g=>`<article class="guest"><span class="chip">${esc(g.rsvp)}</span><h3>${esc(g.name)}</h3><p>${g.count} people · ${[g.morning?'Morning':'',g.evening?'Evening':''].filter(Boolean).join(' & ')}</p><p>Table: ${esc(g.table||'Unassigned')}<br>${esc(g.diet||'No dietary notes')}</p><button class="textbtn" onclick="editGuest('${g.id}')">View / edit →</button></article>`).join('')}</div>${!state.guests.length?empty('Your guest list is ready to grow','Add households and select the events they will attend.'):''}`;
if(page==='Budget')html=heading('Celebrate with clarity.','Amounts are entered by you; no assumed prices.')+`<div class="stats"><div class="stat"><label>ESTIMATED</label><strong>${money(state.tasks.reduce((a,t)=>a+Number(t.estimate||0),0))}</strong></div><div class="stat"><label>AGREED COST</label><strong>${money(cost)}</strong></div><div class="stat"><label>PAID</label><strong>${money(paid)}</strong></div><div class="stat"><label>BALANCE</label><strong>${money(cost-paid)}</strong></div></div><div class="list"><div class="budget-row"><strong>Item</strong><strong>Agreed</strong><strong>Paid</strong><strong>Balance</strong></div>${state.tasks.map(t=>`<div class="budget-row"><button class="textbtn" style="text-align:left;padding:0" onclick="editTask('${t.id}')">${esc(t.title)}</button><span data-label="Agreed">${money(t.cost)}</span><span data-label="Paid">${money(t.paid)}</span><span data-label="Balance">${money(t.cost-t.paid)}</span></div>`).join('')}</div>`;
if(page==='Event day'){let scheduled=state.tasks.filter(t=>t.time).sort((a,b)=>a.time.localeCompare(b.time));html=heading('Be present. We’ll keep the plan.','Assign arrival and setup times inside each task.')+`<div class="notice">Only the mehendi start is confirmed in your brief. Add ritual, vendor and party timings as they are agreed.</div><div class="timeline">${scheduled.map(t=>`<article><div class="eyebrow">${esc(new Date(t.time).toLocaleString('en-IN',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}))}</div><h3>${esc(t.title)}</h3><p>${esc(t.owner||'Assign a coordinator')} · ${esc(t.status)}</p>${btn('Open details',`editTask('${t.id}')`)}</article>`).join('')}</div><h2>Still to schedule</h2><div class="list" style="margin-top:20px">${state.tasks.filter(t=>!t.time&&t.status!=='Completed').map(taskRow).join('')}</div>`}
if(page==='Backups')html=heading('Keep your memories. And your plans.','One portable backup, including every uploaded image.')+`<div class="panel"><h2>Saved on this browser only</h2><p>There is no cloud database or automatic device sync. Use the same browser and site address to return to your plans. Clearing browser storage can erase them.</p><div class="notice">${state.lastBackup?'Last export: '+new Date(state.lastBackup).toLocaleString('en-IN'):'No backup exported yet.'}<br>Store backups somewhere safe. They contain your contacts and private planning details.</div><div class="actions" style="justify-content:flex-start">${btn('Export complete backup','exportBackup()',true)}${btn('Restore from backup',"document.querySelector('#import').click()")}</div><p>Restoring replaces the current plan after confirmation. Export first if you want to preserve your current changes. When moving to Vercel, import your backup at the new address.</p></div>`;$('#app').innerHTML=html}
function searchTasks(el){let pos=el.selectionStart;query=el.value;render();let x=$('input[type=search]');x.focus();x.setSelectionRange(pos,pos)}function empty(t,d){return `<div class="empty"><h3>${t}</h3><p>${d}</p></div>`}function options(a,v){return a.map(x=>`<option ${x===v?'selected':''}>${esc(x)}</option>`).join('')}function field(label,name,val='',type='text',wide=false){return `<label class="field ${wide?'wide':''}">${label}<input name="${name}" type="${type}" value="${esc(val)}" ${['title','name'].includes(name)?'required':''} ${type==='number'?'min="0" step="0.01"':''}></label>`}function select(label,name,vals,v){return `<label class="field">${label}<select name="${name}">${options(vals,v)}</select></label>`}function area(label,name,val){return `<label class="field wide">${label}<textarea name="${name}">${esc(val||'')}</textarea></label>`}function openModal(title,content,save,del=''){let m=$('#modal');m.innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="textbtn" onclick="document.querySelector('#modal').close()" aria-label="Close">✕</button></div><form id="editform"><div class="fields">${content}</div><div class="actions">${del?`<button type="button" class="textbtn danger" onclick="${del}">Delete</button>`:''}<button type="button" class="btn" onclick="document.querySelector('#modal').close()">Cancel</button><button type="submit" class="btn primary">Save changes</button></div></form>`;$('#editform').onsubmit=async e=>{e.preventDefault();let b=e.submitter;b.disabled=true;try{await save(new FormData(e.target))}catch(err){alert(err.message)}finally{b.disabled=false}};m.showModal()}
async function filesToImages(files){let out=[];for(let f of files){if(!['image/jpeg','image/png','image/webp','image/gif'].includes(f.type))throw Error('Please use JPG, PNG, WebP or GIF images.');if(f.size>8*1024*1024)throw Error('Each image must be smaller than 8 MB.');out.push({id:uid(),name:f.name,status:'Inspiration',data:await new Promise((resolve,reject)=>{let r=new FileReader;r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(f)})})}return out}
function editTask(id){let t=state.tasks.find(t=>t.id===id)||{id:uid(),title:'',event:filter||events[1],status:'Not started',priority:'Normal',images:[],subtasks:[]};openModal(id?'The details make the day.':'Add a little detail.',field('Task title','title',t.title,'text',true)+select('Celebration','event',events,t.event)+select('Status','status',statuses,t.status)+field('Responsible person','owner',t.owner)+select('Priority','priority',['Normal','High','Urgent'],t.priority)+field('Due date','due',t.due,'date')+field('Arrival / event time (India local time)','time',t.time,'datetime-local')+`<label class="field wide">Linked contact<select name="contact"><option value="">No contact selected</option>${state.contacts.map(c=>`<option value="${c.id}" ${c.id===t.contact?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label>`+field('Estimate (₹)','estimate',t.estimate||0,'number')+field('Agreed total (₹)','cost',t.cost||0,'number')+field('Paid so far (₹)','paid',t.paid||0,'number')+area('Notes, references, payment details & decisions','notes',t.notes)+area('Subtasks — one per line; start with [x] when complete','subtasks',(t.subtasks||[]).join('\n'))+`<label class="field wide">Photos & receipts (up to 8 MB each)<input name="files" type="file" accept="image/png,image/jpeg,image/webp,image/gif" multiple></label><div class="attachments wide">${t.images.map(i=>`<img src="${i.data}" alt="${esc(i.name)}">`).join('')}</div>`,async f=>{let val=Object.fromEntries(f);delete val.files;for(let k of ['estimate','cost','paid'])val[k]=Number(val[k]);if(val.paid>val.cost)throw Error('Paid amount cannot exceed the agreed total. Update the agreed total first.');val.subtasks=val.subtasks.split('\n').filter(x=>x.trim());val.images=[...t.images,...await filesToImages(f.getAll('files').filter(f=>f.size))];if(await mutate(s=>{let n={...t,...val};let ix=s.tasks.findIndex(x=>x.id===id);if(ix<0)s.tasks.push(n);else s.tasks[ix]=n})){$('#modal').close();toast('Task saved on this device')}},id?`deleteRecord('tasks','${id}')`:'')}
function editContact(id){let c=state.contacts.find(x=>x.id===id)||{id:uid()};openModal('A familiar name. A helping hand.',field('Contact name','name',c.name)+field('Role / service','role',c.role)+field('Phone with country code','phone',c.phone,'tel')+field('Email','email',c.email,'email')+field('Address / location','address',c.address,'text',true)+area('Notes & agreements','notes',c.notes),async f=>{if(await mutate(s=>{let n={...c,...Object.fromEntries(f)},ix=s.contacts.findIndex(x=>x.id===id);ix<0?s.contacts.push(n):s.contacts[ix]=n})){$('#modal').close();toast('Contact saved')}},id?`deleteRecord('contacts','${id}')`:'')}
function editGuest(id){let g=state.guests.find(x=>x.id===id)||{id:uid(),count:1,rsvp:'Awaiting reply'};openModal('A place for everyone.',field('Household / guest name','name',g.name)+field('Number of people','count',g.count,'number')+select('RSVP','rsvp',['Awaiting reply','Confirmed','Declined'],g.rsvp)+field('Phone','phone',g.phone,'tel')+field('Table / seating','table',g.table)+field('Dietary requirements','diet',g.diet)+`<label class="checkbox-line"><input type="checkbox" name="morning" ${g.morning?'checked':''}> Morning pooja</label><label class="checkbox-line"><input type="checkbox" name="evening" ${g.evening?'checked':''}> Evening party</label>`+area('Notes','notes',g.notes),async f=>{let n={...g,...Object.fromEntries(f),count:Number(f.get('count')),morning:f.has('morning'),evening:f.has('evening')};if(!Number.isInteger(n.count)||n.count<1)throw Error('Enter a whole guest count of at least 1.');if(!n.morning&&!n.evening)throw Error('Select at least one celebration.');if(await mutate(s=>{let ix=s.guests.findIndex(x=>x.id===id);ix<0?s.guests.push(n):s.guests[ix]=n})){$('#modal').close();toast('Household saved')}},id?`deleteRecord('guests','${id}')`:'')}
async function deleteRecord(kind,id){if(!confirm('Delete this item? This cannot be undone without a backup.'))return;if(await mutate(s=>{s[kind]=s[kind].filter(x=>x.id!==id);if(kind==='contacts')s.tasks.forEach(t=>{if(t.contact===id)t.contact=''})}))$('#modal').close()}
function addImages(){openModal('Collect something beautiful.',select('Category','category',['Outfits','Flowers','Backdrop 1','Backdrop 2','Backdrop 3','Mehendi','Return gifts','Tables','Lighting','General inspiration'],'General inspiration')+`<label class="field wide">Select images<input type="file" name="files" accept="image/png,image/jpeg,image/webp,image/gif" multiple required></label>`,async f=>{let imgs=await filesToImages(f.getAll('files').filter(x=>x.size));if(!imgs.length)throw Error('Select at least one image.');if(await mutate(s=>s.images.push(...imgs.map(x=>({...x,category:f.get('category')})))))$('#modal').close()})}async function imageStatus(id){await mutate(s=>{let i=[...s.images,...s.tasks.flatMap(t=>t.images)].find(x=>x.id===id),v=['Inspiration','Shortlisted','Approved'];i.status=v[(v.indexOf(i.status)+1)%3]})}async function removeImage(id){if(confirm('Remove this image?'))await mutate(s=>{s.images=s.images.filter(i=>i.id!==id);s.tasks.forEach(t=>t.images=t.images.filter(i=>i.id!==id))})}
async function exportBackup(){let next=structuredClone(state);next.lastBackup=new Date().toISOString();let b=new Blob([JSON.stringify({app:'bharadwaj-planner',version:1,data:next})],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='bharadwaj-backup-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),30000);await commit(next);toast('Backup export requested — keep the downloaded file')}
function validateBackup(b){if(b.app!=='bharadwaj-planner'||b.version!==1||b.data?.version!==1)throw Error('This is not a supported Bharadwaj planner backup.');let s=b.data;for(let k of ['tasks','contacts','guests','images'])if(!Array.isArray(s[k]))throw Error('Backup is missing '+k);let seen=new Set;for(let x of [...s.tasks,...s.contacts,...s.guests,...s.images]){if(typeof x.id!=='string'||!/^[a-f0-9-]{36}$/.test(x.id)||seen.has(x.id))throw Error('Invalid or duplicate record ID.');seen.add(x.id)}for(let t of s.tasks){if(typeof t.title!=='string'||!events.includes(t.event)||!statuses.includes(t.status)||!Array.isArray(t.images)||!Array.isArray(t.subtasks))throw Error('Invalid task record.');for(let k of ['estimate','cost','paid'])if(typeof t[k]!=='number'||!Number.isFinite(t[k])||t[k]<0)throw Error('Invalid budget values.');if(t.paid>t.cost)throw Error('Invalid payment balance.')}for(let c of s.contacts)if(typeof c.name!=='string')throw Error('Invalid contact.');for(let g of s.guests)if(typeof g.name!=='string'||!Number.isInteger(g.count)||g.count<1)throw Error('Invalid guest.');for(let i of [...s.images,...s.tasks.flatMap(t=>t.images)])if(typeof i.id!=='string'||!/^[a-f0-9-]{36}$/.test(i.id)||typeof i.name!=='string'||typeof i.data!=='string'||!/^data:image\/(png|jpeg|webp|gif);base64,[A-Za-z0-9+/=]+$/.test(i.data))throw Error('Invalid image in backup.');return s}
$('#import').onchange=async e=>{try{let f=e.target.files[0];if(!f)return;let next=validateBackup(JSON.parse(await f.text()));if(confirm(`Restore ${next.tasks.length} tasks, ${next.contacts.length} contacts and ${next.guests.length} households? This replaces this browser’s current plan. Export first if needed.`)){if(await commit(next))toast('Backup restored successfully')}}catch(err){alert('Restore failed: '+err.message)}finally{e.target.value=''}};
(async()=>{try{db=await new Promise((resolve,reject)=>{let r=indexedDB.open('bharadwaj-celebrations',1);r.onupgradeneeded=()=>r.result.createObjectStore('planner');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});state=await new Promise((resolve,reject)=>{let r=db.transaction('planner').objectStore('planner').get('data');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});if(!state){state=seed();await write(state)}render()}catch(e){$('#app').innerHTML=empty('Device storage is unavailable','Open this site in a regular browser with storage enabled. Your planner cannot safely save in this session.')}})();
